Execute this JavaScript Promise chain and explain the output.

new Promise((resolve, reject) => {
  setTimeout(() => {
    resolve(1);
  }, 1000);
}).then((result) => {
  console.log(result); // 1
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      resolve(result * 2);
    }, 1000);
  });
}).then((result) => {
  console.log(result); // 2
  return result * 2;
}).then((result) => {
  console.log(result); // 4
});

